SELECT fr.*, u.userName AS username
FROM farm_ranking fr
         LEFT JOIN user u ON fr.userId = u.id AND u.isDelete = 0
WHERE fr.type = #{type}
  AND fr.date = #{date}
ORDER BY fr.todayValue DESC

